import { Arrays, asDefined, assert, ByteArrayInput, ByteArrayOutput, Checksum, isDefined, isInstanceOf, Listeners, Option, panic, Predicates, tryCatch, UUID } from "@opendaw/lib-std";
import { Address } from "./address";
import { PointerField } from "./pointer";
import { DeleteUpdate, NewUpdate, optimizeUpdates, PointerUpdate, PrimitiveUpdate } from "./updates";
import { Dispatchers } from "./dispatchers";
import { GraphEdges } from "./graph-edges";
export class BoxGraph {
    #boxFactory;
    #boxes;
    #deferredPointerUpdates;
    #deferredPointerFields;
    #pendingDeferredNotifications;
    #transactionUpdates;
    #updateListeners;
    #immediateUpdateListeners;
    #transactionListeners;
    #dispatchers;
    #edges;
    #pointerTransactionState;
    #severedPointers;
    #finalizeTransactionObservers;
    #deletionListeners;
    #inTransaction = false;
    #constructingBox = false;
    #rollingBack = false;
    constructor(boxFactory = Option.None) {
        this.#boxFactory = boxFactory;
        this.#boxes = UUID.newSet(box => box.address.uuid);
        this.#deferredPointerUpdates = [];
        this.#deferredPointerFields = new Set();
        this.#pendingDeferredNotifications = [];
        this.#transactionUpdates = [];
        this.#dispatchers = Dispatchers.create();
        this.#updateListeners = new Listeners();
        this.#immediateUpdateListeners = new Listeners();
        this.#transactionListeners = new Listeners();
        this.#edges = new GraphEdges();
        this.#pointerTransactionState = Address.newSet(({ pointer }) => pointer.address);
        this.#severedPointers = [];
        this.#finalizeTransactionObservers = [];
        this.#deletionListeners = UUID.newSet(entry => entry.uuid);
    }
    beginTransaction() {
        assert(!this.#inTransaction, "Transaction already in progress");
        this.#inTransaction = true;
        this.#transactionUpdates.length = 0;
        this.#transactionListeners.proxy.onBeginTransaction();
    }
    abortTransaction() {
        assert(this.#inTransaction, "No transaction in progress");
        this.#rollback();
        // Boxes recreated during the rollback (DeleteUpdate.inverse) defer their pointer updates.
        // They must be resolved (resolvedTo), not discarded, or restored boxes keep unresolved pointers.
        this.#processDeferredPointerUpdates();
        this.#finalizeTransaction();
    }
    endTransaction() {
        assert(this.#inTransaction, "No transaction in progress");
        if (this.#deferredPointerUpdates.length > 0) {
            this.#deferredPointerUpdates.forEach(({ pointerField, update }) => {
                this.#transactionUpdates.push(update);
                this.#prepareDeferredPointerUpdate(pointerField, update);
            });
            this.#deferredPointerUpdates.length = 0;
        }
        if (!this.#rollingBack && this.#boxFactory.nonEmpty()) {
            this.#edges.tryValidateAffected().ifSome(error => {
                this.#rollback();
                this.#finalizeTransaction();
                throw error;
            });
        }
        this.#dispatchDeferredNotifications();
        this.#finalizeTransaction();
    }
    inTransaction() { return this.#inTransaction; }
    constructingBox() { return this.#constructingBox; }
    createBox(name, uuid, constructor) {
        return this.#boxFactory.unwrap("No box-factory installed")(name, this, uuid, constructor);
    }
    stageBox(box, constructor) {
        this.#assertTransaction();
        // Nested construction: the outer box is not staged yet, so pointers into it would refer to a vertex
        // the graph does not have. Create the boxes in sequence and wire them after.
        assert(!this.#constructingBox, "Cannot construct box while other box is constructing");
        // edges are keyed by address, wiring a second box under a staged uuid would cut the first one's edges
        if (this.#boxes.hasKey(box.address.uuid)) {
            return panic(`${box.name} ${box.address.toString()} already staged`);
        }
        if (isDefined(constructor)) {
            this.#constructingBox = true;
            const result = tryCatch(() => constructor(box));
            this.#constructingBox = false;
            if (result.status === "failure") {
                this.#purgeFailedConstruction(box);
                throw result.error;
            }
        }
        const added = this.#boxes.add(box);
        if (!added) {
            this.#purgeFailedConstruction(box);
            return panic(`${box.name} ${box.address.toString()} already staged`);
        }
        const update = new NewUpdate(box.address.uuid, box.name, box.toArrayBuffer());
        if (!this.#rollingBack) {
            this.#transactionUpdates.push(update);
        }
        this.#updateListeners.proxy.onUpdate(update);
        this.#immediateUpdateListeners.proxy.onUpdate(update);
        return box;
    }
    subscribeTransaction(listener) {
        return this.#transactionListeners.subscribe(listener);
    }
    subscribeToAllUpdates(listener) {
        return this.#updateListeners.subscribe(listener);
    }
    subscribeToAllUpdatesImmediate(listener) {
        return this.#immediateUpdateListeners.subscribe(listener);
    }
    subscribeVertexUpdates(propagation, address, procedure) {
        return this.#dispatchers.subscribe(propagation, address, procedure);
    }
    subscribeEndTransaction(observer) { this.#finalizeTransactionObservers.push(observer); }
    subscribeDeletion(uuid, listener) {
        const entry = this.#deletionListeners.getOrCreate(uuid, () => ({ uuid, listeners: new Set() }));
        entry.listeners.add(listener);
        return {
            terminate: () => {
                entry.listeners.delete(listener);
                if (entry.listeners.size === 0) {
                    this.#deletionListeners.removeByKeyIfExist(uuid);
                }
            }
        };
    }
    unstageBox(box) {
        this.#assertTransaction();
        this.#edges.unwatchVerticesOf(box);
        const deleted = this.#boxes.removeByKey(box.address.uuid);
        assert(deleted === box, `${box} could not be found to unstage`);
        const update = new DeleteUpdate(box.address.uuid, box.name, box.toArrayBuffer());
        if (!this.#rollingBack) {
            this.#transactionUpdates.push(update);
        }
        this.#deletionListeners.removeByKeyIfExist(box.address.uuid)?.listeners.forEach(listener => listener());
        this.#updateListeners.proxy.onUpdate(update);
        this.#immediateUpdateListeners.proxy.onUpdate(update);
    }
    findBox(uuid) {
        return this.#boxes.opt(uuid);
    }
    findVertex(address) {
        return this.#boxes.opt(address.uuid).flatMap(box => box.searchVertex(address.fieldKeys));
    }
    boxes() { return this.#boxes.values(); }
    // Edges naming a box the graph does not hold. Deserialization and a merged document are the only ways in,
    // since refer() demands a live vertex.
    unresolvablePointers() {
        return this.#boxes.values().flatMap(box => box.outgoingEdges()
            .filter(([, targetAddress]) => this.findVertex(targetAddress).isEmpty())
            .map(([pointer]) => pointer));
    }
    // Make a pointer whose target is gone indistinguishable from one that was never set, so every consumer's
    // existing "not set" handling applies unchanged. Never deletes: who cannot live without its target is a
    // separate, later decision. Order-independent, so every peer computes the same result.
    //
    // Deliberately NOT part of deserialization: a partial graph (a clipboard subset) points outside itself on
    // purpose. Only a caller that claims its graph should be whole may ask for this.
    //
    // Clearing a mandatory pointer leaves the graph momentarily invalid, by design, until the caller rebuilds
    // the target or removes the owner. So when this opens its own transaction it closes it WITHOUT validation.
    // Called inside an open transaction it just clears, and that caller's endTransaction validates as usual.
    clearUnresolvablePointers() {
        const pointers = this.unresolvablePointers();
        if (pointers.length === 0) {
            return 0;
        }
        const nested = this.#inTransaction;
        if (!nested) {
            this.beginTransaction();
        }
        pointers.forEach(pointer => pointer.targetAddress = Option.None);
        if (!nested) {
            this.#finalizeWithoutValidation();
        }
        console.warn(`[BoxGraph] cleared ${pointers.length} pointer(s) whose target is missing`);
        return pointers.length;
    }
    edges() { return this.#edges; }
    checksum() {
        const checksum = new Checksum();
        this.boxes().forEach(box => box.write(checksum));
        return checksum.result();
    }
    onPrimitiveValueUpdate(field, oldValue, newValue) {
        this.#assertTransaction();
        if (field.isAttached() && !this.#constructingBox) {
            const update = new PrimitiveUpdate(field.address, field.serialization(), oldValue, newValue);
            if (!this.#rollingBack) {
                this.#transactionUpdates.push(update);
            }
            this.#dispatchers.dispatch(update);
            this.#updateListeners.proxy.onUpdate(update);
            this.#immediateUpdateListeners.proxy.onUpdate(update);
        }
    }
    onPointerAddressUpdated(pointerField, oldValue, newValue) {
        this.#assertTransaction();
        // https://github.com/andremichelle/openDAW/issues/480
        if (!this.#constructingBox && !pointerField.isAttached()) {
            return;
        }
        if (oldValue.nonEmpty()) {
            this.#edges.disconnect(pointerField);
        }
        if (newValue.nonEmpty()) {
            this.#edges.connect(pointerField, newValue.unwrap());
        }
        const update = new PointerUpdate(pointerField.address, oldValue, newValue);
        if (this.#constructingBox) {
            this.#deferredPointerUpdates.push({ pointerField, update });
            this.#deferredPointerFields.add(pointerField);
        }
        else {
            // Resolve constructor updates and this one before listeners run, so a listener's change resolves last
            const updates = [...this.#takeDeferredPointerUpdates(pointerField), update];
            updates.forEach(pointerUpdate => {
                if (!this.#rollingBack) {
                    this.#transactionUpdates.push(pointerUpdate);
                }
                this.#resolvePointerUpdate(pointerField, pointerUpdate);
            });
            updates.forEach(pointerUpdate => {
                this.#dispatchers.dispatch(pointerUpdate);
                this.#updateListeners.proxy.onUpdate(pointerUpdate);
            });
            this.#immediateUpdateListeners.proxy.onUpdate(update);
        }
    }
    // Listeners can take from and add to the array, so detach it first and repeat until it stays empty
    #processDeferredPointerUpdates() {
        while (this.#deferredPointerUpdates.length > 0) {
            this.#deferredPointerUpdates.splice(0).forEach(({ pointerField, update }) => this.#processPointerVertexUpdate(pointerField, update));
        }
    }
    #takeDeferredPointerUpdates(pointerField) {
        if (!this.#deferredPointerFields.delete(pointerField)) {
            return [];
        }
        const updates = this.#deferredPointerUpdates
            .filter(deferred => deferred.pointerField === pointerField)
            .map(({ update }) => update);
        Arrays.removeIf(this.#deferredPointerUpdates, deferred => deferred.pointerField === pointerField);
        return updates;
    }
    #processPointerVertexUpdate(pointerField, update) {
        this.#resolvePointerUpdate(pointerField, update);
        this.#dispatchers.dispatch(update);
        this.#updateListeners.proxy.onUpdate(update);
    }
    #prepareDeferredPointerUpdate(pointerField, update) {
        this.#resolvePointerUpdate(pointerField, update);
        this.#pendingDeferredNotifications.push({ pointerField, update });
    }
    #resolvePointerUpdate(pointerField, update) {
        const { oldAddress, newAddress } = update;
        pointerField.resolvedTo(newAddress.flatMap(address => this.findVertex(address)));
        const optState = this.#pointerTransactionState.opt(pointerField.address);
        optState.match({
            none: () => this.#pointerTransactionState.add({
                pointer: pointerField,
                initial: oldAddress,
                final: newAddress,
                index: this.#pointerTransactionState.size()
            }),
            some: state => state.final = newAddress
        });
    }
    #dispatchDeferredNotifications() {
        for (const { update } of this.#pendingDeferredNotifications) {
            this.#dispatchers.dispatch(update);
            this.#updateListeners.proxy.onUpdate(update);
        }
        this.#pendingDeferredNotifications.length = 0;
    }
    #finalizeTransaction() {
        this.#deferredPointerFields.clear();
        this.#severedPointers.splice(0).forEach(({ pointer, target }) => {
            target.pointerHub.onRemoved(pointer);
            if (this.#pointerTransactionState.hasKey(pointer.address)) {
                return;
            }
            this.findVertex(pointer.address).ifSome(replacement => {
                if (isInstanceOf(replacement, PointerField)
                    && replacement.targetAddress.mapOr(address => address.equals(target.address), false)) {
                    target.pointerHub.onAdded(replacement);
                }
            });
        });
        // a listener that throws must not leave the graph in a transaction forever
        const notified = tryCatch(() => this.#pointerTransactionState.values()
            .toSorted((a, b) => a.index - b.index)
            .forEach(({ pointer, initial, final }) => {
            if (!initial.equals(final)) {
                initial.ifSome(address => this.findVertex(address).unwrapOrUndefined()?.pointerHub.onRemoved(pointer));
                final.ifSome(address => this.findVertex(address).unwrapOrUndefined()?.pointerHub.onAdded(pointer));
            }
        }));
        this.#pointerTransactionState.clear();
        this.#inTransaction = false;
        if (notified.status === "failure") {
            throw notified.error;
        }
        while (this.#finalizeTransactionObservers.length > 0) {
            this.#finalizeTransactionObservers.splice(0).forEach(observer => observer());
            if (this.#finalizeTransactionObservers.length > 0) {
                console.debug(`${this.#finalizeTransactionObservers.length} new observers while notifying`);
            }
        }
        this.#transactionListeners.proxy.onEndTransaction(this.#rollingBack);
        this.#rollingBack = false;
    }
    #rollback() {
        this.#rollingBack = true;
        // the rollback recreates deleted boxes as new instances, so listeners must let go of the old pointers
        this.#pointerTransactionState.forEach(({ pointer, initial }) => {
            if (this.findBox(pointer.box.address.uuid).mapOr(box => box === pointer.box, false)) {
                return;
            }
            initial.flatMap(address => this.findVertex(address))
                .ifSome(target => this.#severedPointers.push({ pointer, target }));
        });
        for (const { update } of this.#deferredPointerUpdates) {
            this.#transactionUpdates.push(update);
        }
        this.#deferredPointerUpdates.length = 0;
        // Phantom boxes (created AND deleted in this transaction) net to nothing, and their deferred
        // pointer updates sit at the end of the list, out of chronological order — replaying them raw
        // would resurrect edges on unstaged boxes. Collapse them first, like the undo path does.
        const updates = optimizeUpdates(this.#transactionUpdates.splice(0));
        // An update whose vertex is absent (e.g. the graph diverged through an external participant)
        // has nothing to invert. Warn so unexpected occurrences stay visible in error reports.
        for (let i = updates.length - 1; i >= 0; i--) {
            const update = updates[i];
            if ((update instanceof PointerUpdate || update instanceof PrimitiveUpdate)
                && this.findVertex(update.address).isEmpty()) {
                console.warn(`[BoxGraph] rollback skips ${update.type}-update, vertex not found at ${update.address.toString()}`);
                continue;
            }
            update.inverse(this);
        }
        this.#pendingDeferredNotifications.length = 0;
        this.#edges.clearAffected();
        this.#pointerTransactionState.clear();
        this.#transactionUpdates.length = 0;
    }
    // Cleanup after a box constructor threw (or staging failed): the box is not part of the graph,
    // so its deferred pointer updates, outgoing edges and watch registrations must not leak.
    #purgeFailedConstruction(box) {
        for (let i = this.#deferredPointerUpdates.length - 1; i >= 0; i--) {
            if (this.#deferredPointerUpdates[i].pointerField.box === box) {
                this.#deferredPointerUpdates.splice(i, 1);
            }
        }
        this.#edges.outgoingEdgesOf(box).forEach(([source]) => this.#edges.disconnect(source));
        this.#edges.forgetVerticesOf(box);
    }
    findOrphans(rootBox) {
        const connectedBoxes = this.#collectAllConnectedBoxes(rootBox);
        return this.boxes().filter(box => !connectedBoxes.has(box));
    }
    #collectAllConnectedBoxes(rootBox) {
        const visited = new Set();
        const queue = [rootBox];
        while (queue.length > 0) {
            const box = queue.pop();
            if (visited.has(box)) {
                continue;
            }
            visited.add(box);
            this.#collectPointersFromBox(box).forEach(pointer => {
                pointer.targetAddress.ifSome(address => {
                    this.findBox(address.uuid).ifSome(targetBox => {
                        if (!visited.has(targetBox)) {
                            queue.push(targetBox);
                        }
                    });
                });
            });
            for (const pointer of box.incomingEdges()) {
                if (!visited.has(pointer.box)) {
                    queue.push(pointer.box);
                }
            }
        }
        return visited;
    }
    #collectPointersFromBox(box) {
        const pointers = [];
        const collectFromFields = (fields) => {
            for (const field of fields) {
                field.accept({
                    visitPointerField: (p) => pointers.push(p),
                    visitObjectField: (o) => collectFromFields(o.fields()),
                    visitArrayField: (a) => collectFromFields(a.fields())
                });
            }
        };
        collectFromFields(box.fields());
        return pointers;
    }
    dependenciesOf(root, options = {}) {
        const excludeBox = isDefined(options.excludeBox) ? options.excludeBox : Predicates.alwaysFalse;
        const alwaysFollowMandatory = isDefined(options.alwaysFollowMandatory) ? options.alwaysFollowMandatory : false;
        const stopAtResources = isDefined(options.stopAtResources) ? options.stopAtResources : false;
        const boxes = new Set();
        const pointers = new Set();
        const trace = (box, isStartingBox = false) => {
            if (boxes.has(box) || (!isStartingBox && excludeBox(box))) {
                return;
            }
            boxes.add(box);
            if (stopAtResources && isDefined(box.resource)) {
                box.incomingEdges()
                    .forEach(pointer => {
                    pointers.add(pointer);
                    const targetsField = pointer.targetAddress.mapOr(address => !address.isBox(), false);
                    if (pointer.mandatory && targetsField) {
                        if (box.resource === "shared") {
                            const isOwnershipField = pointer.targetAddress
                                .flatMap(address => this.findVertex(address))
                                .mapOr(vertex => vertex.pointerRules.mandatory, false);
                            if (isOwnershipField) {
                                return;
                            }
                        }
                        trace(pointer.box);
                    }
                });
                return;
            }
            box.outgoingEdges()
                .filter(([pointer]) => !pointers.has(pointer))
                .forEach(([source, targetAddress]) => {
                // A concurrent merge can leave an edge naming a box the document no longer holds. Record
                // the pointer regardless so Box.delete defers it (unstage rejects a box with live edges),
                // and skip the walk instead of panicking. Repairing it is deterministicReconcile's job.
                pointers.add(source);
                this.findVertex(targetAddress).match({
                    none: () => console.warn(`[BoxGraph] skipping dangling ${source.toString()} -> ${targetAddress.toString()}`),
                    some: targetVertex => {
                        if (targetVertex.pointerRules.mandatory &&
                            (alwaysFollowMandatory || targetVertex.pointerHub.incoming()
                                .filter(p => p.targetAddress.mapOr(address => address.equals(targetAddress), false))
                                .every(pointer => pointers.has(pointer)))) {
                            trace(targetVertex.box);
                        }
                    }
                });
            });
            box.incomingEdges()
                .forEach(pointer => {
                pointers.add(pointer);
                if (pointer.mandatory) {
                    trace(pointer.box);
                }
            });
        };
        const startingBoxes = Array.isArray(root) ? root : [root];
        startingBoxes.forEach(startingBox => trace(startingBox, true));
        startingBoxes.forEach(startingBox => boxes.delete(startingBox));
        return { boxes, pointers: Array.from(pointers).reverse() };
    }
    verifyPointers() {
        this.#edges.validateRequirements();
        let count = 0 | 0;
        const verify = (vertex) => {
            for (const field of vertex.fields()) {
                field.accept({
                    visitPointerField: (pointer) => {
                        if (pointer.targetAddress.nonEmpty()) {
                            const isResolved = pointer.targetVertex.nonEmpty();
                            const inGraph = this.findVertex(pointer.targetAddress.unwrap()).nonEmpty();
                            assert(isResolved, `pointer ${pointer.address} is broken`);
                            assert(inGraph, `Cannot find target for pointer ${pointer.address}`);
                            count++;
                        }
                    },
                    visitObjectField: (object) => verify(object)
                });
            }
        };
        this.#boxes.forEach((box) => verify(box));
        console.debug("verification complete.");
        return { count };
    }
    debugBoxes() {
        console.table(this.#boxes.values().reduce((dict, box) => {
            dict[UUID.toString(box.address.uuid)] = {
                class: box.name,
                "incoming links": box.incomingEdges().length,
                "outgoing links": box.outgoingEdges().length,
                "est. memory (bytes)": box.estimateMemory()
            };
            return dict;
        }, {}));
    }
    debugDependencies() {
        console.debug("Dependencies:");
        this.boxes().forEach(box => {
            console.debug(`\t${box}`);
            for (const dependency of this.dependenciesOf(box).boxes) {
                console.debug(`\t\t${dependency}`);
            }
        });
    }
    addressToDebugPath(address) {
        return address.flatMap(address => address.isBox()
            ? this.findBox(address.uuid).map(box => box.name)
            : this.findBox(address.uuid)
                .flatMap(box => box.searchVertex(address.fieldKeys)
                .map(vertex => vertex.isField() ? vertex.debugPath : panic("Unknown address"))));
    }
    toArrayBuffer() {
        const output = ByteArrayOutput.create();
        const boxes = this.#boxes.values();
        output.writeInt(boxes.length);
        boxes.forEach(box => {
            const buffer = box.serialize();
            output.writeInt(buffer.byteLength);
            output.writeBytes(new Int8Array(buffer));
        });
        return output.toArrayBuffer();
    }
    fromArrayBuffer(arrayBuffer, validate = true) {
        assert(this.#boxes.isEmpty(), "Cannot call fromArrayBuffer if boxes is not empty");
        const input = new ByteArrayInput(arrayBuffer);
        const numBoxes = input.readInt();
        this.beginTransaction();
        const boxes = [];
        for (let i = 0; i < numBoxes; i++) {
            const length = input.readInt();
            const int8Array = new Int8Array(length);
            input.readBytes(int8Array);
            const boxStream = new ByteArrayInput(int8Array.buffer);
            const creationIndex = boxStream.readInt();
            const name = boxStream.readString();
            const uuid = UUID.fromDataInput(boxStream);
            boxes.push({ creationIndex, name, uuid, boxStream });
        }
        boxes
            .sort((a, b) => a.creationIndex - b.creationIndex)
            .forEach(({ name, uuid, boxStream }) => this.createBox(name, uuid, box => box.read(boxStream)));
        if (validate) {
            this.endTransaction();
        }
        else {
            this.#finalizeWithoutValidation();
        }
    }
    toJSON() {
        const result = {};
        for (const box of this.#boxes.values()) {
            result[box.address.toString()] = {
                name: box.name,
                fields: asDefined(box.toJSON())
            };
        }
        return result;
    }
    fromJSON(value, validate = true) {
        if (typeof value !== "object" || value === null || Array.isArray(value)) {
            return panic("Expected object");
        }
        this.beginTransaction();
        const entries = Object.entries(value);
        for (const [uuid, { name, fields }] of entries) {
            this.createBox(name, UUID.parse(uuid), box => {
                const result = tryCatch(() => box.fromJSON(fields));
                if (result.status === "failure") {
                    console.warn(result.error);
                }
            });
        }
        if (validate) {
            this.endTransaction();
        }
        else {
            this.#finalizeWithoutValidation();
        }
    }
    #finalizeWithoutValidation() {
        this.#processDeferredPointerUpdates();
        this.#edges.clearAffected();
        this.#finalizeTransaction();
    }
    #assertTransaction() {
        assert(this.#inTransaction, () => "Modification only prohibited in transaction mode.");
    }
}
