import { GrooveFunctionBox, GrooveOffsetBox, GrooveRandomBox, GrooveShuffleBox, GrooveStackBox, GrooveStackEntryBox, AudioUnitBox, CubedDeviceBox, TrackBox, NoteClipBox, NoteRegionBox, RootBox, ValueClipBox, ValueRegionBox, ZeitgeistDeviceBox } from "@opendaw/studio-boxes";
import { Pointers } from "@opendaw/studio-enums";
import { ByteArrayInput, isDefined, isInstanceOf, Option, panic, Strings, UUID } from "@opendaw/lib-std";
import { GrooveAdapter } from "./GrooveBoxAdapter";
import { GrooveFunctionType } from "./GrooveFunctionBoxAdapter";
// Every caller is inside an `editing.modify`, so nothing here opens a transaction
export var Grooves;
(function (Grooves) {
    Grooves.Kinds = [
        { kind: "shuffle", label: "Shuffle" },
        { kind: "power", label: "Power" },
        { kind: "s-curve", label: "S-Curve" },
        { kind: "random", label: "Random" },
        { kind: "offset", label: "Offset" },
        { kind: "stack", label: "Stack" }
    ];
    Grooves.labelOf = (kind) => Grooves.Kinds.find(entry => entry.kind === kind)?.label ?? panic(`Unknown groove kind ${kind}`);
    const KindVisitor = {
        visitGrooveShuffleBox: () => "shuffle",
        visitGrooveFunctionBox: (box) => box.function.getValue() === GrooveFunctionType.SCurve ? "s-curve" : "power",
        visitGrooveRandomBox: () => "random",
        visitGrooveOffsetBox: () => "offset",
        visitGrooveStackBox: () => "stack"
    };
    Grooves.kindOf = (box) => box.accept(KindVisitor) ?? panic(`${box.name} is no groove`);
    Grooves.asGrooveBox = (box) => box.accept({
        visitGrooveShuffleBox: (box) => box,
        visitGrooveFunctionBox: (box) => box,
        visitGrooveRandomBox: (box) => box,
        visitGrooveOffsetBox: (box) => box,
        visitGrooveStackBox: (box) => box
    }) ?? panic(`${box.name} is no groove`);
    Grooves.isGlobal = (context, groove) => context.rootBoxAdapter.box.groove.targetAddress
        .mapOr(address => UUID.equals(address.uuid, groove.address.uuid), false);
    Grooves.globalGroove = (context) => Grooves.asGrooveBox(context.rootBoxAdapter.box.groove.targetVertex.unwrap("No global groove").box);
    Grooves.users = (groove) => groove.pointerHub.filter(Pointers.Groove);
    Grooves.targets = (groove) => Grooves.users(groove).filter(pointer => !isInstanceOf(pointer.box, RootBox));
    Grooves.create = (context, kind, label) => {
        const { boxGraph } = context;
        const uuid = UUID.generate();
        const box = kind === "shuffle" ? GrooveShuffleBox.create(boxGraph, uuid)
            : kind === "power" ? GrooveFunctionBox.create(boxGraph, uuid, box => box.function.setValue(GrooveFunctionType.Power))
                : kind === "s-curve" ? GrooveFunctionBox.create(boxGraph, uuid, box => box.function.setValue(GrooveFunctionType.SCurve))
                    : kind === "random" ? GrooveRandomBox.create(boxGraph, uuid)
                        : kind === "offset" ? GrooveOffsetBox.create(boxGraph, uuid)
                            : GrooveStackBox.create(boxGraph, uuid);
        attach(context, box, label ?? Grooves.labelOf(kind));
        return box;
    };
    Grooves.replace = (context, groove, kind) => {
        if (Grooves.kindOf(groove) === kind) {
            return groove;
        }
        if (isInstanceOf(groove, GrooveFunctionBox) && (kind === "power" || kind === "s-curve")) {
            groove.function.setValue(kind === "s-curve" ? GrooveFunctionType.SCurve : GrooveFunctionType.Power);
            return groove;
        }
        const replacement = Grooves.create(context, kind);
        Grooves.users(groove).slice().forEach(pointer => pointer.refer(replacement));
        const label = groove.label.getValue();
        const index = groove.index.getValue();
        const amount = amountOf(groove);
        const duration = durationOf(groove);
        groove.delete();
        replacement.label.setValue(label);
        replacement.index.setValue(index);
        if (!isInstanceOf(replacement, GrooveStackBox) && !isInstanceOf(replacement, GrooveOffsetBox)) {
            if (isDefined(amount)) {
                replacement.amount.setValue(amount);
            }
            if (isDefined(duration)) {
                replacement.duration.setValue(duration);
            }
        }
        return replacement;
    };
    Grooves.duplicate = (context, groove) => {
        const input = new ByteArrayInput(groove.toArrayBuffer());
        const copy = Grooves.asGrooveBox(context.boxGraph.createBox(groove.name, UUID.generate(), box => box.read(input)));
        copy.collection.defer();
        attach(context, copy, groove.label.getValue());
        if (isInstanceOf(groove, GrooveStackBox) && isInstanceOf(copy, GrooveStackBox)) {
            Grooves.entriesOf(groove).forEach(entry => entry.groove.targetVertex.ifSome(target => GrooveStackEntryBox.create(context.boxGraph, UUID.generate(), box => {
                box.stack.refer(copy.entries);
                box.groove.refer(target.box);
                box.index.setValue(entry.index.getValue());
            })));
        }
        return copy;
    };
    Grooves.makeUnique = (context, groove, user) => {
        const copy = Grooves.duplicate(context, groove);
        user.refer(copy);
        return copy;
    };
    Grooves.isTimelineBox = (box) => isInstanceOf(box, NoteRegionBox) || isInstanceOf(box, ValueRegionBox)
        || isInstanceOf(box, NoteClipBox) || isInstanceOf(box, ValueClipBox);
    Grooves.pointerOf = (box) => Grooves.isTimelineBox(box) ? Option.wrap(box.groove) : Option.None;
    Grooves.playedAt = (context, box, origin) => Grooves.pointerOf(box).flatMap(pointer => pointer.targetVertex).map(({ box: groove }) => {
        const adapter = Grooves.adapterOf(context, Grooves.asGrooveBox(groove));
        return (position) => origin + adapter.warp(position - origin);
    });
    Grooves.sharedOf = (boxes) => {
        const targets = boxes.map(box => Grooves.pointerOf(box).flatMap(pointer => pointer.targetVertex).map(vertex => vertex.box));
        const first = targets.at(0);
        if (!isDefined(first) || first.isEmpty()) {
            return Option.None;
        }
        const groove = first.unwrap();
        return targets.every(target => target.contains(groove)) ? Option.wrap(Grooves.asGrooveBox(groove)) : Option.None;
    };
    Grooves.unitOf = (box) => (isInstanceOf(box, NoteRegionBox) || isInstanceOf(box, ValueRegionBox) ? box.regions : box.clips).targetVertex
        .flatMap(({ box: track }) => isInstanceOf(track, TrackBox) ? track.tracks.targetVertex : Option.None)
        .flatMap(({ box: unit }) => isInstanceOf(unit, AudioUnitBox) ? Option.wrap(unit) : Option.None);
    Grooves.deleteAll = (context, grooves, mode) => {
        const doomed = new Set(grooves.filter(groove => !Grooves.isGlobal(context, groove)));
        if (doomed.size === 0) {
            return;
        }
        const global = Grooves.globalGroove(context);
        doomed.forEach(groove => Grooves.users(groove).slice().forEach(pointer => {
            if (mode === "fallback" && !Grooves.isTimelineBox(pointer.box) && !isInstanceOf(pointer.box, CubedDeviceBox)) {
                if (isInstanceOf(pointer.box, GrooveStackEntryBox)
                    && Grooves.wouldContain(global, Grooves.asGrooveBox(pointer.box.stack.targetVertex
                        .unwrap("Entry without stack").box))) {
                    Grooves.unassign(pointer);
                }
                else {
                    pointer.refer(global);
                }
            }
            else {
                Grooves.unassign(pointer);
            }
        }));
        const remaining = context.rootBoxAdapter.grooves.adapters()
            .filter(adapter => !doomed.has(adapter.box))
            .map(adapter => adapter.box);
        doomed.forEach(groove => groove.delete());
        reindex(remaining);
    };
    // a stack entry without its member is deleted
    Grooves.unassign = (pointer) => {
        if (isInstanceOf(pointer.box, GrooveStackEntryBox)) {
            const stack = pointer.box.stack.targetVertex.map(vertex => Grooves.asGrooveBox(vertex.box));
            pointer.box.delete();
            stack.ifSome(stack => {
                if (isInstanceOf(stack, GrooveStackBox)) {
                    reindexEntries(Grooves.entriesOf(stack));
                }
            });
        }
        else {
            pointer.defer();
        }
    };
    Grooves.move = (context, grooves, target) => {
        const moved = new Set(grooves);
        if (moved.has(target) || moved.size === 0) {
            return;
        }
        const ordered = context.rootBoxAdapter.grooves.adapters().map(adapter => adapter.box);
        const stationary = ordered.filter(box => !moved.has(box));
        const insertAt = stationary.indexOf(target);
        if (insertAt < 0) {
            return;
        }
        const dragged = ordered.filter(box => moved.has(box));
        const before = ordered.indexOf(dragged[0]) < ordered.indexOf(target);
        stationary.splice(before ? insertAt + 1 : insertAt, 0, ...dragged);
        reindex(stationary);
    };
    Grooves.wouldContain = (groove, stack, visited = new Set()) => {
        if (groove === stack) {
            return true;
        }
        if (!isInstanceOf(groove, GrooveStackBox) || visited.has(groove)) {
            return false;
        }
        // a cycle from merged edits in a live room ends here
        visited.add(groove);
        return Grooves.entriesOf(groove).some(entry => entry.groove.targetVertex
            .mapOr(vertex => Grooves.wouldContain(Grooves.asGrooveBox(vertex.box), stack, visited), false));
    };
    Grooves.canAddToStack = (stack, groove) => !Grooves.wouldContain(groove, stack);
    Grooves.addToStack = (context, stack, groove) => {
        if (!Grooves.canAddToStack(stack, groove)) {
            return;
        }
        GrooveStackEntryBox.create(context.boxGraph, UUID.generate(), box => {
            box.stack.refer(stack.entries);
            box.groove.refer(groove);
            box.index.setValue(Grooves.entriesOf(stack).length);
        });
    };
    Grooves.removeFromStack = (entry) => Grooves.unassign(entry.groove);
    Grooves.moveInStack = (stack, entry, to) => {
        const entries = Grooves.entriesOf(stack).slice();
        const from = entries.indexOf(entry);
        if (from < 0 || to < 0 || to >= entries.length || from === to) {
            return;
        }
        entries.splice(from, 1);
        entries.splice(to, 0, entry);
        reindexEntries(entries);
    };
    Grooves.entriesOf = (stack) => stack.entries.pointerHub.incoming()
        .map(pointer => pointer.box)
        .filter((box) => isInstanceOf(box, GrooveStackEntryBox) && box.isAttached())
        .sort((left, right) => left.index.getValue() - right.index.getValue());
    Grooves.userOf = (pointer) => {
        const box = pointer.box;
        if (isInstanceOf(box, ZeitgeistDeviceBox)) {
            return { type: "zeitgeist", box };
        }
        if (isInstanceOf(box, RootBox)) {
            return { type: "project", box };
        }
        if (Grooves.isTimelineBox(box)) {
            return { type: "timeline", box };
        }
        if (isInstanceOf(box, GrooveStackEntryBox)) {
            const stack = box.stack.targetVertex.map(vertex => vertex.box);
            if (stack.nonEmpty() && isInstanceOf(stack.unwrap(), GrooveStackBox)) {
                return { type: "stack", box: stack.unwrap(), entry: box };
            }
        }
        return { type: "other", box };
    };
    Grooves.adapterOf = (context, groove) => context.boxAdapters.adapterFor(groove, GrooveAdapter.checkType);
    const amountOf = (groove) => isInstanceOf(groove, GrooveStackBox) || isInstanceOf(groove, GrooveOffsetBox) ? null : groove.amount.getValue();
    const durationOf = (groove) => isInstanceOf(groove, GrooveStackBox) || isInstanceOf(groove, GrooveOffsetBox) ? null : groove.duration.getValue();
    const reindex = (grooves) => grooves.forEach((groove, index) => groove.index.setValue(index));
    const reindexEntries = (entries) => entries.forEach((entry, index) => entry.index.setValue(index));
    const listed = (context) => context.rootBoxAdapter.box.grooves.pointerHub.incoming().map(pointer => Grooves.asGrooveBox(pointer.box));
    const attach = (context, box, label) => {
        const existing = listed(context);
        box.label.setValue(Strings.getUniqueName(existing.map(groove => groove.label.getValue()), label));
        box.index.setValue(existing.length);
        box.collection.refer(context.rootBoxAdapter.box.grooves);
    };
})(Grooves || (Grooves = {}));
